Lemma aptr_eqb_spec' (a b : aptr) : reflect (a = b) (aptr_eqb a b).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 2 "S50!2'1#2#1!2'1#3#2!2'1#4#3!3+4'0#5#4%~R!3+4+20,6!3+4'0#3#2$a;R'0$b;R'0&b0;R0+2&E;R!2,3+2#1!3+4+21#1!1-2RN$b;R+2%E;R!3+4+2!2'1#5#4#1!2+5!3+4'0#6#5#2#22$E;R!3+4+22,6!2,73&H;R$a;R'0$b;R'0!5'84%~R!3+4'0#2#1!3+4+21,6%~R!3+4+2!2'1#2#1,6!3+4'0#3#2$~R4$~R%~R!3+4'0#3#2!3+4+2!2'1#4#3,6#2!2'9#2#1%a;R'0%b;R'04!3#1#6#5#2$E;R!3+4+22,:!2,;3vd$H;R3!7'<'0#5$a;R'0%E;R!3+4+2!2'1#1#6,:+=$E;R!3+4+2!2'1#5#5,:&E;R!6'>+2!2'1#6#6$b;R+2!3+4+2#1,:#1,6!1'?#6!3+4+2,6,:&H;R!6'>+2,6$e;R+2-2RN$b;R+2w#12+@+=,A,:#1+=!2'B+=#1#6#1#2!1'C3#1").
Qed.
End CEIL_WRAP_2.


Ltac case_ptr x y := destruct (aptr_eqb_spec' x y) as [?EQ|?NE]; [subst x|].
