Definition hkind (st : mstate) (h : lhead) (x : aptr) : Prop :=
  match h with
  | LActive sc => is_gm st x /\ m_sizeclass (get_meta_rec st x) = sc
  | LFree => ~ is_gm st x
  end.

Lemma free_head_not_gm st LB c h : KINV st LB c -> c_free_meta_head (ctx st) = Some h -> ~ is_gm st h.
